func (q *Queries) UpsertBotCaptureCursor(ctx context.Context, arg UpsertBotCaptureCursorParams) error {
	_, err := q.db.ExecContext(ctx, upsertBotCaptureCursor,
		arg.ThreadID,
		arg.SessionID,
		arg.EntryCount,
		arg.LastEntryID,
		arg.UpdatedAt,
	)
	return err
}
